$('.view-rating').on('click', function(){
    $('#avalicaoModal').modal('show');
});

var page = 1;
var canLoad = true;

$('.content-avalicao').on('scroll', function(){

    if($(this).scrollTop() + $(this).height() >= $('#conteudo').height() && canLoad){
        var codigo_usuario = $('#codigo_usuario').attr('codigo_usuario');
        page++;
        loadMoreData(page, codigo_usuario);
    }

});

function loadMoreData(page, codigo_usuario){
    $.ajax(
        {
            url: '/buscaAvalicoes/'+codigo_usuario+'?page=' + page,
            type: "get",
            beforeSend: function()
            {
                $(".loader").show()
            },
            complete:function(data){
                $(".loader").delay(400).fadeOut("slow");
            },
            success: function(data){
                canLoad = true;
                $("#conteudo").append(data.html);
            },
            error: function(data){
                canLoad = false;
                var errors = data.responseJSON;
            }
        });
}

$( "#todosComentarios" ).click(function() {
    var codigo_anuncio = $(this).attr('codigo_anuncio');
    _token = $('input[name="_token"]').val();
    $.ajax({
        type: "POST",
        url: '/anuncio/'+codigo_anuncio+'/buscaComentarios',
        data: {_token : _token},
        beforeSend: function(){
            $(".loader").show()
        },
        complete:function(data){
            $(".loader").delay(600).fadeOut("slow");
        },
        success: function(data) {
            $('#conteudo-comentarios').html('');
            $('#conteudo-comentarios').html(data.html);
            $('#modalComentarios').modal('show');

        },
        error: function(data){
            var errors = data.responseJSON;
            if(errors.hasOwnProperty('error')){
                $("#error-message").html(errors.error);
            }
            else{
                $("#error-message").html(data.responseJSON);
            }
            $('#ModalError').modal('show');
        }
    });

});


